program='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 3 and (nx,ny) not in seen:
                        seen.add((nx,ny))
                        q.append((nx,ny))
            boxes.append((min(x for x,y in cells), max(x for x,y in cells), min(y for x,y in cells), max(y for x,y in cells)))
    centers = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 and any(r0 <= r <= r1 and c0 <= c <= c1 for r0,r1,c0,c1 in boxes):
                centers.append((r,c))
    out = [row[:] for row in grid]
    for r,c in centers:
        for x in range(max(0,r-1), min(h,r+2)):
            for y in range(max(0,c-1), min(w,c+2)):
                out[x][y] = 1
    for r,c in centers:
        out[r][c] = 2
    return out
'''
